// src/services/api.js
import axios from 'axios';

// TRỎ ĐÚNG VÀO CỔNG 5001 CỦA C# NHÉ BỐ!
const API_BASE_URL = 'http://localhost:5002/api';

const api = axios.create({
    baseURL: API_BASE_URL,
    headers: { 'Content-Type': 'application/json' },
});

// Trạm gác lúc đi: tự kẹp Token
api.interceptors.request.use((config) => {
    const token = localStorage.getItem('token');
    if (token) config.headers.Authorization = `Bearer ${token}`;
    return config;
}, (error) => Promise.reject(error));

// Trạm gác lúc về: Xử lý văng đăng nhập
api.interceptors.response.use(
    (response) => response,
    (error) => {
        if (error.response?.status === 401) {
            localStorage.removeItem('token');
            localStorage.removeItem('user');
            window.location.href = '/login';
        }
        return Promise.reject(error);
    }
);

// --- DANH SÁCH API SERVICE TỔNG HỢP ---

export const authApi = {
    login: (userName, password) => api.post('/auth/login', { Username: userName, Password: password }),
    register: (userData) => api.post('/auth/register', userData),
};

export const productsApi = {
    getAll: (params) => api.get('/products', { params }),
    getById: (id) => api.get(`/products/${id}`),
    getFeatured: () => api.get('/products/featured'),
    create: (data) => api.post('/products', data),
    update: (id, data) => api.put(`/products/${id}`, data),
    delete: (id) => api.delete(`/products/${id}`),
    filter: (name, startDate, endDate) =>
        api.get('/products/filter', { params: { name, startDate, endDate } })
};

export const categoriesApi = {
    getAll: () => api.get('/categories'),
    getById: (id) => api.get(`/categories/${id}`),
    create: (data) => api.post('/categories', data),
    update: (id, data) => api.put(`/categories/${id}`, data),
    delete: (id) => api.delete(`/categories/${id}`),
};

export const usersApi = {
    getAll: (params) => api.get('/users', { params }),
    getById: (id) => api.get(`/users/${id}`),
    create: (data) => api.post('/users', data),
    update: (id, data) => api.put(`/users/${id}`, data),
    delete: (id) => api.delete(`/users/${id}`),
};

export const ordersApi = {
    getAll: () => api.get('/orders/all'),
    updateStatus: (id, status) => api.put(`/orders/${id}/status`, { status }),
    checkout: (orderData) => api.post('/orders/checkout', orderData)
};

// CÁC CỤC DÀNH RIÊNG CHO KHÁCH HÀNG (GIỎ HÀNG, COUPON, BÌNH LUẬN)
export const cartsApi = {
    getByUserId: (userId) => api.get(`/carts/${userId}`),
    addToCart: (cartData) => api.post('/carts/add', cartData),
    removeFromCart: (itemId) => api.delete(`/carts/remove/${itemId}`),
};

export const couponsApi = {
    check: (code) => api.get(`/coupons/check?code=${code}`)
};

export const reviewsApi = {
    getByProductId: (productId) => api.get(`/reviews/product/${productId}`),
    create: (data) => api.post('/reviews', data),
};

export default api;
